const q = new URLSearchParams(location.search);
if (q.has('shot')){
  S.mode = 'play';
  if (q.get('shot') === 'off'){
    S.train.moving = false; S.player.aboard = false; S.player.x = 120; S.player.y = -240;
    S.train.fuel = 40; S.inv = { wood:2, coal:1, scrap:1, food:2 };
  } else if (q.get('shot') === 'zom'){
    S.train.moving = false; S.player.aboard = false; S.player.x = 150; S.player.y = -260;
    spawnZs({ x: 90, y: -300, n: 4 });
  } else if (q.get('shot') === 'win'){ S.mode='win'; showOverlay('win'); }
  else if (q.get('shot') === 'dead'){ damage(120); }
  else { S.player.aboard = true; }
  // warm up deterministically so camera/UI settle before the first frame
  const n = parseInt(q.get('sim') || '90', 10);
  for (let i = 0; i < n; i++) { try { update(1/60); } catch(e){} }
}

