input.newString:
function drawPlayer(x,y,dir,atkT){
  ctx.fillStyle = 'rgba(0,0,0,.35)'; ctx.beginPath(); ctx.ellipse(x+3,y+7,10,5,0,0,6.3); ctx.fill();
  // swing arc
  if (atkT > .22){
    ctx.strokeStyle = 'rgba(255,240,200,.85)'; ctx.lineWidth = 4;
    ctx.beginPath(); ctx.arc(x, y, 30, dir-.9, dir+.9); ctx.stroke();
  }
  // coat
  ctx.fillStyle = '#31405e'; ctx.beginPath(); ctx.arc(x, y, 10.5, 0, 6.3); ctx.fill();
  ctx.strokeStyle = '#56688a'; ctx.lineWidth = 2; ctx.stroke();
  // head
  ctx.fillStyle = '#e8c39a'; ctx.beginPath(); ctx.arc(x, y, 7, 0, 6.3); ctx.fill();
  // cap covering the back of the head
  ctx.fillStyle = '#2b2e34';
  ctx.beginPath(); ctx.moveTo(x, y);
  ctx.arc(x, y, 7.4, dir + Math.PI - 1.25, dir + Math.PI + 1.25); ctx.closePath(); ctx.fill();
  // eyes
  const fx = x + Math.cos(dir)*4.4, fy = y + Math.sin(dir)*4.4;
  ctx.fillStyle = '#20242a';
  ctx.beginPath(); ctx.arc(fx - Math.sin(dir)*2.6, fy + Math.cos(dir)*2.6, 1.2, 0, 6.3); ctx.fill();
  ctx.beginPath(); ctx.arc(fx + Math.sin(dir)*2.6, fy - Math.cos(dir)*2.6, 1.2, 0, 6.3); ctx.fill();
}

